async def act(page):
    """
    1) Attempt to dismiss an obvious popup/overlay using accessibility-role-centric selectors.
    2) Call the site-aware helper create_curated_collection_by_search(...) to run the visible
       search for 'crypto' (this helper must be used when available). If it returns results,
       print them and click the third-to-last article's preferred target.
    3) If the helper returns no results, navigate to the "Sample Page" link (present in the
       document root) and perform a manual accessible search there: find the complementary
       region or a searchbox/textbox, fill 'crypto', trigger the search, wait for results,
       then click the third-to-last article (prefer link, then heading, then article).

    The final action in this function (if it navigates away) is the click on the target result.
    """
    import asyncio

    async def _safe_count(locator):
        try:
            return await locator.count()
        except Exception:
            return 0

    async def try_dismiss_overlay():
        # Try to close role=dialog by clicking a named close/dismiss button inside it
        dialogs = page.get_by_role("dialog")
        dlg_count = await _safe_count(dialogs)
        close_names = ["close", "dismiss", "ok", "×", "x", "✕", "close popup", "dismiss popup"]
        for i in range(dlg_count):
            dlg = dialogs.nth(i)
            for name in close_names:
                btn = dlg.get_by_role("button", name=name)
                if await _safe_count(btn) > 0:
                    try:
                        await btn.nth(0).click()
                        await page.wait_for_timeout(300)
                        return True
                    except Exception:
                        pass
            # fallback: first button inside dialog
            inner_buttons = dlg.get_by_role("button")
            if await _safe_count(inner_buttons) > 0:
                try:
                    await inner_buttons.nth(0).click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass

        # Try top-level buttons named 'close' or 'dismiss'
        close_btn = page.get_by_role("button", name="close")
        if await _safe_count(close_btn) > 0:
            try:
                await close_btn.nth(0).click()
                await page.wait_for_timeout(300)
                return True
            except Exception:
                pass
        dismiss_btn = page.get_by_role("button", name="dismiss")
        if await _safe_count(dismiss_btn) > 0:
            try:
                await dismiss_btn.nth(0).click()
                await page.wait_for_timeout(300)
                return True
            except Exception:
                pass

        # Heuristic sweep: clickable buttons with close-like text
        all_buttons = page.get_by_role("button")
        all_count = await _safe_count(all_buttons)
        for i in range(all_count):
            btn = all_buttons.nth(i)
            try:
                aria = (await btn.get_attribute("aria-label")) or ""
            except Exception:
                aria = ""
            try:
                title = (await btn.get_attribute("title")) or ""
            except Exception:
                title = ""
            try:
                txt = (await btn.inner_text()) or ""
            except Exception:
                txt = ""
            low = (aria + " " + title + " " + txt).lower()
            if "close" in low or "dismiss" in low or txt.strip() in ["×", "x", "✕"]:
                try:
                    await btn.click()
                    await page.wait_for_timeout(300)
                    return True
                except Exception:
                    pass
        return False

    # Try dismissing overlay first (best-effort). Helper itself will goto('/') when called.
    try:
        await try_dismiss_overlay()
    except Exception:
        pass

    # 1) Use the knowledge-base helper to perform the visible search for 'crypto'.
    try:
        results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
    except Exception:
        results = []

    # Print raw helper results exactly as returned.
    print(results)

    # If helper returned no results, try dismissing overlays and retry once.
    if not results:
        try:
            await try_dismiss_overlay()
        except Exception:
            pass
        try:
            results = await create_curated_collection_by_search(page, "crypto", max_results=0, resolve_links=True)
        except Exception:
            results = []
        print(results)

    async def click_third_to_last_from_page():
        # Click the third-to-last article in role=main -> role=article
        main = page.get_by_role("main")
        articles = main.get_by_role("article")
        article_count = await _safe_count(articles)
        if article_count < 3:
            raise Exception(f"Not enough search results to click the third-to-last (found {article_count}).")
        target_index = article_count - 3
        target_article = articles.nth(target_index)
        # Prefer link
        links = target_article.get_by_role("link")
        if await _safe_count(links) > 0:
            await links.nth(0).click()
            return
        # Fallback heading
        headings = target_article.get_by_role("heading")
        if await _safe_count(headings) > 0:
            await headings.nth(0).click()
            return
        # Final fallback: click article container
        await target_article.click()
        return

    # If helper returned results, assume results are rendered and try to click third-to-last.
    if results:
        # attempt to click using the accessible tree rendered by the helper
        try:
            await click_third_to_last_from_page()
            return
        except Exception:
            # if clicking failed, fall through to navigate to Sample Page and try manual flow
            pass

    # If no results from helper (or clicking failed), navigate to the "Sample Page" link and try manual accessible search there.
    sample_link = page.get_by_role("link", name="Sample Page")
    if await _safe_count(sample_link) > 0:
        await sample_link.nth(0).click()
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(1)

    # Now attempt to find complementary region or searchbox/textbox and perform search manually
    comp = page.get_by_role("complementary")
    if await _safe_count(comp) > 0:
        # prefer searchbox then textbox inside complementary
        sb = comp.get_by_role("searchbox")
        if await _safe_count(sb) > 0:
            search_input = sb.nth(0)
        else:
            tb = comp.get_by_role("textbox")
            if await _safe_count(tb) > 0:
                search_input = tb.nth(0)
            else:
                search_input = None
    else:
        # fallback to any searchbox/textbox on the page
        sb = page.get_by_role("searchbox")
        if await _safe_count(sb) > 0:
            search_input = sb.nth(0)
        else:
            tb = page.get_by_role("textbox")
            if await _safe_count(tb) > 0:
                search_input = tb.nth(0)
            else:
                search_input = None

    if search_input is None:
        raise Exception("Search input not found on the page; cannot perform search.")

    # Fill and trigger the search
    try:
        await search_input.fill("crypto")
    except Exception:
        try:
            await search_input.focus()
            await search_input.type("crypto")
        except Exception:
            pass

    triggered = False
    # try button inside complementary
    if await _safe_count(comp) > 0:
        comp_btn = comp.get_by_role("button")
        if await _safe_count(comp_btn) > 0:
            try:
                await comp_btn.nth(0).click()
                triggered = True
            except Exception:
                triggered = False
    if not triggered:
        # try a button named 'search'
        search_btn = page.get_by_role("button", name="search")
        if await _safe_count(search_btn) > 0:
            try:
                await search_btn.nth(0).click()
                triggered = True
            except Exception:
                triggered = False
    if not triggered:
        try:
            await search_input.press("Enter")
            triggered = True
        except Exception:
            triggered = False

    # Wait for results rendering
    try:
        await page.get_by_role("main").wait_for(state="visible", timeout=5000)
    except Exception:
        try:
            await page.wait_for_load_state("networkidle")
        except Exception:
            await asyncio.sleep(1)

    # Finally click the third-to-last article
    await click_third_to_last_from_page()

